using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckMattressRacing.Editor {
public static class MattressAuthoring {
 public const string Folder="TruckMattressRacing",Scene="Assets/TruckMattressRacing/Scenes/TruckMattressRacing.unity";
 public static void Create(){var m=SportsEventAuthoring.Begin<MattressMatch>(Folder);m.setup.count=8;m.option=0;m.NormalizeSetup();m.feedback.clips=LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create().Concat(new[]{AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckCornhole/Audio/Launch.wav")}).ToArray();var terrainPath="Assets/"+Folder+"/Materials/Downhill meadow.asset";var data=AssetDatabase.LoadAssetAtPath<TerrainData>(terrainPath);if(data==null){data=new TerrainData();AssetDatabase.CreateAsset(data,terrainPath);}data.heightmapResolution=513;data.size=new Vector3(530,330,740);data.terrainLayers=new[]{AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/PinwheelStudio/Vista/Personal/Samples/TerrainLayers/Grass Light/Grass_Light_VistaSample.terrainlayer"),AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/3D Haven/Path Painter II/Editor/Demo/Terrains/DocsTerrain/TerrainLayers/stdMudRocky.terrainlayer"),AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/PinwheelStudio/Vista/Personal/Samples/TerrainLayers/Sand/Sand_VistaSample.terrainlayer")};data.alphamapResolution=256;var alpha=new float[256,256,3];for(int z=0;z<256;z++)for(int x=0;x<256;x++){float mud=Mathf.Clamp01((Mathf.Sin(z*.12f)+Mathf.PerlinNoise(x*.07f,z*.08f)-.6f)*.65f);float hardpack=Mathf.SmoothStep(.4f,.85f,Mathf.Sin(z*.08f+1))* .8f;alpha[z,x,2]=hardpack;alpha[z,x,1]=mud*(1-hardpack);alpha[z,x,0]=1-alpha[z,x,1]-hardpack;}data.SetAlphamaps(0,0,alpha);var terrain=Terrain.CreateTerrainGameObject(data).GetComponent<Terrain>();terrain.name="Broad banked downhill mattress meadow";terrain.transform.position=new Vector3(-265,-285,-15);terrain.drawInstanced=true;terrain.heightmapPixelError=4;var terrainMat=SportsEventAuthoring.Mat(Folder,"Mattress hill terrain",Color.white);terrainMat.shader=Shader.Find("Universal Render Pipeline/Terrain/Lit");terrain.materialTemplate=terrainMat;m.course=m.gameObject.AddComponent<MattressCourse>();m.course.terrain=terrain;
 var contact=SportsEventAuthoring.Contact(Folder,"Sliding mattress cloth",.075f,.32f);var brace=SportsEventAuthoring.Contact(Folder,"Braced mattress cloth",.11f,.12f);var foam=SportsEventAuthoring.Mat(Folder,"Warm woven mattress sides",new Color(.82f,.78f,.65f),.08f);var fabric=SportsEventAuthoring.Mat(Folder,"Actual patterned Bed fabric",Color.white,.16f);fabric.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/HQ_ResidentialHouse/Textures/Bed/Bed_d.tga");fabric.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/HQ_ResidentialHouse/Textures/Bed/Bed_n.tga"));fabric.SetTexture("_OcclusionMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/HQ_ResidentialHouse/Textures/Bed/Bed_ao.tga"));fabric.EnableKeyword("_NORMALMAP");fabric.SetFloat("_BumpScale",.5f);var meshes=MattressMeshes();m.racers=new MattressRacer[8];m.identities=new TextMesh[8];for(int i=0;i<8;i++){var t=SportsEventAuthoring.Truck(m,Folder,"Mattress platform competitor "+(i+1),new Vector3((i-3.5f)*5.2f,.4f,0),i);SportsRallyAuthoring.FitTruck(t);var binding=t.GetComponent<SportsWheelMeshBinding>();for(int w=0;w<binding.meshes.Length;w++){var physical=t.wheels[w].wheel.rotatingContainer;binding.meshes[w].rotation=physical.rotation*binding.alignment[w];binding.meshes[w].position=physical.position-binding.meshes[w].TransformVector(binding.centers[w]);}UnityEngine.Object.DestroyImmediate(binding);t.Power(false);t.visuals.localPosition+=Vector3.up*.65f;t.shape.center+=Vector3.up*.65f;t.body.mass=18;t.body.centerOfMass=new Vector3(0,.08f,0);t.body.maxLinearVelocity=32;t.body.maxAngularVelocity=10;t.body.linearDamping=.025f;t.body.angularDamping=.25f;var pad=t.gameObject.AddComponent<BoxCollider>();pad.center=Vector3.zero;pad.size=new Vector3(3.4f,.65f,5.2f);pad.sharedMaterial=contact;var cushion=new GameObject("Patterned actual mattress and soft quilt").transform;cushion.SetParent(t.transform,false);MeshPart(cushion,"Rounded real bed mattress",meshes[0],foam);MeshPart(cushion,"Actual bed quilt",meshes[1],fabric);var racer=t.gameObject.AddComponent<MattressRacer>();racer.match=m;racer.truck=t;racer.slot=i;racer.cushion=cushion;racer.pad=pad;racer.slideMaterial=contact;racer.braceMaterial=brace;m.racers[i]=racer;m.identities[i]=SportsEventAuthoring.Label("Mattress identity "+i,m.setup.players[i].name,t.transform.position+Vector3.up*3,.14f,m.setup.players[i].color);m.identities[i].gameObject.AddComponent<SportsPerCameraBillboard>();}
 m.views=SportsRallyAuthoring.Views(m,m.racers.Select(r=>r.truck).ToArray());m.course.weather=SportsChaosAuthoring.Weather(m,Folder);m.views.weather=m.course.weather;m.course.Generate(5147,1);for(int i=0;i<8;i++)m.racers[i].transform.SetPositionAndRotation(m.course.Spawn(i,0),m.course.Rotation(0));m.replay=SportsRallyAuthoring.Replay(m,m.racers.Select(r=>r.transform).ToArray());m.replay.capacity=2400;m.replay.interval=.05f;Dress(m);MattressPresentationAuthoring.Install(m);SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);SportsEventAuthoring.Save(Folder);Validate();}
 static void MeshPart(Transform parent,string name,Mesh mesh,Material material){var g=new GameObject(name);g.transform.SetParent(parent,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=material;}
 static Mesh[] MattressMeshes(){var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/HQ_ResidentialHouse/Objects/Bed.FBX").GetComponentsInChildren<MeshFilter>(true).OrderByDescending(f=>f.sharedMesh.vertexCount).First().sharedMesh;var vertices=source.vertices;var triangles=source.triangles;var parents=Enumerable.Range(0,vertices.Length).ToArray();Func<int,int> find=null;find=i=>parents[i]==i?i:parents[i]=find(parents[i]);Action<int,int> join=(a,b)=>{a=find(a);b=find(b);if(a!=b)parents[b]=a;};var weld=new Dictionary<Vector3Int,int>();for(int i=0;i<vertices.Length;i++){var v=vertices[i];var key=new Vector3Int(Mathf.RoundToInt(v.x*100000),Mathf.RoundToInt(v.y*100000),Mathf.RoundToInt(v.z*100000));if(weld.TryGetValue(key,out int other))join(i,other);else weld[key]=i;}for(int i=0;i<triangles.Length;i+=3){join(triangles[i],triangles[i+1]);join(triangles[i],triangles[i+2]);}var groups=Enumerable.Range(0,vertices.Length).GroupBy(i=>find(i)).Select(g=>{var b=new Bounds(vertices[g.First()],Vector3.zero);foreach(var i in g)b.Encapsulate(vertices[i]);return new {id=g.Key,bounds=b,count=g.Count()};}).ToArray();var mattress=groups.Where(g=>g.bounds.size.x>1.4f&&g.bounds.size.z>1.7f&&g.bounds.size.y>.15f&&g.bounds.size.y<.25f).OrderBy(g=>Mathf.Abs(g.bounds.center.y-.307f)).First();var quilt=groups.Where(g=>g.bounds.size.x>1.4f&&g.bounds.size.z>1.4f&&g.bounds.size.y>.3f&&g.bounds.size.y<.7f).OrderByDescending(g=>g.count).First();Debug.Log("MATTRESS_ACTUAL_BED_COMPONENTS mattress="+mattress.count+" "+mattress.bounds+" quilt="+quilt.count+" "+quilt.bounds);var result=new Mesh[2];for(int part=0;part<2;part++){int id=part==0?mattress.id:quilt.id;var output=new List<Vector3>();var uv=new List<Vector2>();var remap=new Dictionary<int,int>();var indices=new List<int>();for(int k=0;k<triangles.Length;k+=3){if(find(triangles[k])!=id)continue;for(int j=0;j<3;j++){int original=triangles[k+j];if(!remap.TryGetValue(original,out int mapped)){mapped=output.Count;remap[original]=mapped;var v=vertices[original];float x=Mathf.Clamp(v.x,-.80f,.80f)*(3.4f/1.56f),z=v.z*(5.2f/1.86f);float y=part==0?(v.y-.307f)*(.65f/.2f):.325f+(v.y-.407f)*.6f;output.Add(new Vector3(x,y,z));uv.Add(source.uv[original]);}indices.Add(mapped);}}var mesh=new Mesh{name=part==0?"Derived actual bed mattress":"Derived actual bed quilt"};mesh.SetVertices(output);mesh.SetUVs(0,uv);mesh.SetTriangles(indices,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();string path="Assets/"+Folder+"/Materials/"+mesh.name+".asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing==null)AssetDatabase.CreateAsset(mesh,path);else{existing.Clear();existing.SetVertices(output);existing.SetUVs(0,uv);existing.SetTriangles(indices,0);existing.RecalculateNormals();existing.RecalculateTangents();existing.RecalculateBounds();existing.UploadMeshData(false);EditorUtility.SetDirty(existing);UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;}result[part]=mesh;}return result;}
 static void Dress(MattressMatch m){var root=new GameObject("Bedtime downhill scenery and checkpoint flags").transform;for(int i=0;i<80;i++){float z=i/2*18;float x=m.course.Center(z)+(i%2==0?-1:1)*(46+i%4*4);LWS.TruckBaseJumping.Editor.BaseSkyAuthoring.Scenery(root,m.course.Surface(new Vector3(x,0,z)),i%5==0?3:8+i%4,i%5!=0,Folder);}var gold=SportsEventAuthoring.Mat(Folder,"Checkpoint gold",new Color(1,.65f,.08f));for(int cp=0;cp<m.course.checkpoints.Length;cp++){float z=m.course.checkpoints[cp];for(int side=-1;side<=1;side+=2){var p=m.course.Surface(new Vector3(m.course.Center(z)+side*43,0,z));SportsRallyAuthoring.Prop(root,"Assets/RoadPropsPack/URP/Prefabs/TrafficCone_URP.prefab",p,new Vector3(2,3,2));var marker=SportsEventAuthoring.Label("Ordered checkpoint "+cp,"FLAG "+(cp+1),p+Vector3.up*4,.35f,new Color(1,.84f,.3f));marker.gameObject.AddComponent<SportsPerCameraBillboard>();}var caption=SportsEventAuthoring.Label("Checkpoint direction "+cp,cp==7?"FINISH":"DOWNHILL",m.course.Surface(new Vector3(m.course.Center(z),0,z))+Vector3.up*7,.18f,Color.white);caption.gameObject.AddComponent<SportsPerCameraBillboard>();}for(int i=0;i<14;i++){float z=45+i*43;SportsRallyAuthoring.Prop(root,i%2==0?"Assets/RoadPropsPack/URP/Prefabs/TireStacked01_URP.prefab":"Assets/ConstructionPropsBundle/URP/Prefabs/SM_Barrel01 Variant.prefab",m.course.Surface(new Vector3(m.course.Center(z)+(i%2==0?-39:39),0,z)),new Vector3(2,2,2));}}
 public static void Validate(){EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<MattressMatch>();if(m==null||m.racers.Length!=8||m.views.views.Length!=4||m.replay.ghosts.Length!=(m.world!=null?9:8)||m.course.checkpoints.Length!=8||m.course.terrain==null)throw new Exception("Mattress saved references incomplete");foreach(var r in m.racers){if(r.truck.wheels.Any(w=>w.enabled)||r.GetComponent<SportsWheelMeshBinding>()!=null)throw new Exception("Mattresses must have no powered or hidden driving tires");if(r.cushion.GetComponentsInChildren<MeshRenderer>().Length<2)throw new Exception("Actual mattress/quilt art missing");}foreach(var ghost in m.replay.ghosts)if(ghost.GetComponentsInChildren<Rigidbody>(true).Length>0||ghost.GetComponentsInChildren<Collider>(true).Length>0)throw new Exception("Mattress replay must be render-only");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("One mattress listener required");Debug.Log("MATTRESS_SAVED_VALIDATED actual bed meshes, eight gravity platforms, zero powered tires");}
}
}
